function isPlain(value) {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

export function mergeLayers(...layers) {
  const result = {};
  for (const layer of layers) {
    for (const [key, value] of Object.entries(layer)) {
      if (value === undefined) continue;
      const previous = Object.hasOwn(result, key) ? result[key] : undefined;
      const next = isPlain(value)
        ? mergeLayers(isPlain(previous) ? previous : {}, value)
        : value !== null && typeof value === 'object'
          ? structuredClone(value)
          : value;
      // Define an own data property, including for keys such as "__proto__".
      Object.defineProperty(result, key, {
        value: next, enumerable: true, configurable: true, writable: true,
      });
    }
  }
  return result;
}

