import assert from 'node:assert/strict';
import { mergeLayers } from './src/merge.mjs';
import { loadConfig } from './src/config.mjs';
const a = { endpoint: '/a', retries: 3, nested: { a: 1, b: [ { x: 1 } ] }, list: [1, 2], flag: true, nullable: 1 };
const b = { endpoint: '', retries: 0, nested: { a: undefined, c: false }, list: [{ y: 2 }], flag: false, nullable: null };
const before = structuredClone([a, b]);
const result = loadConfig(a, {}, b);
assert.deepEqual(result, { endpoint: '', retries: 0, nested: { a: 1, b: [{ x: 1 }], c: false }, list: [{ y: 2 }], flag: false, nullable: null });
result.nested.b[0].x = 9; result.list[0].y = 9;
assert.deepEqual([a, b], before);
assert.deepEqual(mergeLayers({x: 1}, {x: undefined}), {x: 1});
assert.deepEqual(mergeLayers({x: [1]}, {x: {a: 2}}), {x: {a: 2}});
assert.throws(() => loadConfig({endpoint: null, retries: 0}), /endpoint/);
assert.throws(() => loadConfig({endpoint: '', retries: -1}), /retries/);
const safe = mergeLayers(JSON.parse('{"__proto__":{"polluted":true}}'));
assert.equal(Object.getPrototypeOf(safe), Object.prototype);
assert.equal(Object.hasOwn(safe, '__proto__'), true);
assert.equal({}.polluted, undefined);
console.log('Additional contract checks passed');
